@block PandaTrajectory begin
    # 1 kHz Cartesian trajectory of the Panda flange (sampled firmware, D28). Generated by
    # design/build_library.py from design/design.py.
    #
    # 5 waypoints p0..p4; segment k runs from t0 + k (Tm + Td) for Tm seconds, rest to
    # rest with the quintic s = tau^3 (10 - 15 tau + 6 tau^2), then rests Td at the waypoint:
    #
    #   p(t) = p_k + (p_{k+1} - p_k) s(tau),   psi(t) = yaw_k + (yaw_{k+1} - yaw_k) s(tau)
    #
    # The flange keeps its home orientation (pointing down) turned by psi about the world
    # vertical: a slerp about z between the waypoint orientations. `g` is the target pose on
    # the D-MB6 chart (qw, qx, qy, qz, x, y, z), the input of the IK and of the 3D target marker.
    @parameters begin
        px0::Real = 0.3068905665929411, [unit = "m", description = "Waypoint 0 x"]
        py0::Real = -6.946435977616828e-17, [unit = "m", description = "Waypoint 0 y"]
        pz0::Real = 0.5902820523028393, [unit = "m", description = "Waypoint 0 z"]
        yaw0::Real = -2.263489573738043e-16, [unit = "rad", description = "Waypoint 0 turn about the vertical"]
        px1::Real = 0.45, [unit = "m", description = "Waypoint 1 x"]
        py1::Real = 0.2, [unit = "m", description = "Waypoint 1 y"]
        pz1::Real = 0.42, [unit = "m", description = "Waypoint 1 z"]
        yaw1::Real = 0.4182243295792291, [unit = "rad", description = "Waypoint 1 turn about the vertical"]
        px2::Real = 0.45, [unit = "m", description = "Waypoint 2 x"]
        py2::Real = -0.2, [unit = "m", description = "Waypoint 2 y"]
        pz2::Real = 0.42, [unit = "m", description = "Waypoint 2 z"]
        yaw2::Real = -0.4182243295792291, [unit = "rad", description = "Waypoint 2 turn about the vertical"]
        px3::Real = 0.35, [unit = "m", description = "Waypoint 3 x"]
        py3::Real = -0.12, [unit = "m", description = "Waypoint 3 y"]
        pz3::Real = 0.65, [unit = "m", description = "Waypoint 3 z"]
        yaw3::Real = -0.3302973548292537, [unit = "rad", description = "Waypoint 3 turn about the vertical"]
        px4::Real = 0.3068905665929411, [unit = "m", description = "Waypoint 4 x"]
        py4::Real = -6.946435977616828e-17, [unit = "m", description = "Waypoint 4 y"]
        pz4::Real = 0.5902820523028393, [unit = "m", description = "Waypoint 4 z"]
        yaw4::Real = -2.263489573738043e-16, [unit = "rad", description = "Waypoint 4 turn about the vertical"]
        t0::Real = 0.2, [unit = "s", min = 0, description = "Start of the first segment"]
        Tm::Real = 0.9, [unit = "s", min = 1.0e-3, description = "Duration of each segment"]
        Td::Real = 0.25, [unit = "s", min = 0, description = "Rest at each waypoint"]
        qhw::Real = 2.8533601266142735e-17, [unit = "1", description = "Home flange orientation quaternion w"]
        qhx::Real = 0.9238795325112867, [unit = "1", description = "Home flange orientation quaternion x"]
        qhy::Real = -0.3826834323650899, [unit = "1", description = "Home flange orientation quaternion y"]
        qhz::Real = 2.996591748872674e-17, [unit = "1", description = "Home flange orientation quaternion z"]
    end
    @inputs tm::Real, [unit = "s"]
    @outputs begin
        g::Vec{7} = [2.8533601266142735e-17, 0.9238795325112867, -0.38268343236508995, 2.996591748872673e-17, 0.3068905665929411, -6.946435977616828e-17, 0.5902820523028393]
        px::Real = 0.3068905665929411, [unit = "m"]
        py::Real = -6.946435977616828e-17, [unit = "m"]
        pz::Real = 0.5902820523028393, [unit = "m"]
        segment::Real = 0.0, [unit = "1", description = "Current segment (0 before the first move)"]
    end
    @discrete Ts = 0.001 begin
        x = px0
        y = py0
        z = pz0
        psi = yaw0
        seg = 0.0
        ts = t0 + 0.0 * (Tm + Td)
        if tm >= ts
            tau = clamp((tm - ts) / Tm, 0.0, 1.0)
            s = tau * tau * tau * (10.0 - 15.0 * tau + 6.0 * tau * tau)
            x = px0 + (px1 - px0) * s
            y = py0 + (py1 - py0) * s
            z = pz0 + (pz1 - pz0) * s
            psi = yaw0 + (yaw1 - yaw0) * s
            seg = 1.0
        end
        ts = t0 + 1.0 * (Tm + Td)
        if tm >= ts
            tau = clamp((tm - ts) / Tm, 0.0, 1.0)
            s = tau * tau * tau * (10.0 - 15.0 * tau + 6.0 * tau * tau)
            x = px1 + (px2 - px1) * s
            y = py1 + (py2 - py1) * s
            z = pz1 + (pz2 - pz1) * s
            psi = yaw1 + (yaw2 - yaw1) * s
            seg = 2.0
        end
        ts = t0 + 2.0 * (Tm + Td)
        if tm >= ts
            tau = clamp((tm - ts) / Tm, 0.0, 1.0)
            s = tau * tau * tau * (10.0 - 15.0 * tau + 6.0 * tau * tau)
            x = px2 + (px3 - px2) * s
            y = py2 + (py3 - py2) * s
            z = pz2 + (pz3 - pz2) * s
            psi = yaw2 + (yaw3 - yaw2) * s
            seg = 3.0
        end
        ts = t0 + 3.0 * (Tm + Td)
        if tm >= ts
            tau = clamp((tm - ts) / Tm, 0.0, 1.0)
            s = tau * tau * tau * (10.0 - 15.0 * tau + 6.0 * tau * tau)
            x = px3 + (px4 - px3) * s
            y = py3 + (py4 - py3) * s
            z = pz3 + (pz4 - pz3) * s
            psi = yaw3 + (yaw4 - yaw3) * s
            seg = 4.0
        end
        # orientation: Rz(psi) applied to the home orientation, q = (cos psi/2, 0, 0, sin psi/2) (x) q_home
        cz = cos(0.5 * psi)
        sz = sin(0.5 * psi)
        g[1] = cz * qhw - sz * qhz
        g[2] = cz * qhx - sz * qhy
        g[3] = cz * qhy + sz * qhx
        g[4] = cz * qhz + sz * qhw
        g[5] = x
        g[6] = y
        g[7] = z
        px = x
        py = y
        pz = z
        segment = seg
    end
end
